const body = $json.body ?? $json;
const spotifyUrl = String(body.spotifyUrl ?? body.query ?? '').trim();

if (!/^https:\/\/open\.spotify\.com\/(?:intl-[^/]+\/)?track\/[A-Za-z0-9]+(?:\?[^\s]*)?$/i.test(spotifyUrl)) {
  throw new Error('spotifyUrl must be a Spotify track URL');
}

const jobId = `${Date.now()}-${Math.floor(Math.random() * 1000000)}`;
const payload = {
  jobId,
  operation: 'download',
  queries: [spotifyUrl],
  spotifyUrl,
  format: 'mp3',
  delivery: 'none',
  options: {
    audioProviders: [],
    lyricsProviders: ['genius', 'musixmatch', 'azlyrics', 'synced'],
    overwrite: 'force',
    restrict: 'strict',
    threads: 4,
    maxRetries: 3,
    maxFilenameLength: 180,
  },
};

return {
  json: {
    jobId,
    payloadB64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
  },
};

const raw = String($json.stdout ?? '').trim();
let result;

try {
  result = JSON.parse(raw);
} catch {
  throw new Error(String($json.stderr ?? raw ?? 'Runner returned invalid JSON').slice(0, 1000));
}

const tracks = Array.isArray(result.tracks) ? result.tracks : [];
const files = Array.isArray(result.files) ? result.files : [];

return {
  json: {
    status: String(result.status ?? 'failed'),
    jobId: String(result.jobId ?? ''),
    exitCode: Number(result.exitCode ?? 1),
    fileCount: files.length,
    track: tracks[0] ? {
      title: String(tracks[0].title ?? ''),
      artist: String(tracks[0].artist ?? ''),
      lyricsAvailable: Boolean(String(tracks[0].lyrics ?? '').trim()),
    } : null,
    error: result.error ? String(result.error).slice(0, 500) : null,
  },
};
